        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z"/></svg>
      </div>
      <div>
        <h3 class="text-lg font-bold text-amber-900 mb-2">Key Point</h3>
        <p class="text-amber-800 text-lg">Every post should have one purpose: Help, Proof, or Invitation. Use the simple formula: Opening, Value, Next Action. Only use client results or images with the right permission and after removing private information.</p>
      </div>
    </div>
  </div>

  <!-- Action Steps -->
  <div class="bg-gradient-to-br from-emerald-50 to-teal-50 rounded-2xl p-6 border-2 border-emerald-200">
    <div class="flex items-center gap-3 mb-5">
      <div class="w-12 h-12 rounded-xl bg-emerald-100 flex items-center justify-center">
        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg>
      </div>
      <h3 class="text-xl font-bold text-emerald-900">Action Steps — Adapt, Preview, and Schedule</h3>
    </div>
    
    <div class="space-y-4">
      
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">1</div>
        <div>
          <p class="font-semibold text-slate-900">Choose a Purpose</p>
          <p class="text-slate-600 text-sm">Decide if your post will Help, provide Proof, or be an Invitation.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">2</div>
        <div>
          <p class="font-semibold text-slate-900">Write the Post</p>
          <p class="text-slate-600 text-sm">Follow the formula: Opening, Value, Next Action. Add media and test links.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">3</div>
        <div>
          <p class="font-semibold text-slate-900">Save as Draft</p>
          <p class="text-slate-600 text-sm">Save the post as a draft and ask someone to read it and identify the one action it asks them to take.</p>
        </div>
      </div>
    </div>
  </div>
</div>',
      title = 'Build One Useful Post',
      lesson_number = 3,
      sort_order = 3,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Build One Useful Post';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Build One Useful Post

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 16 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 16 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'build-useful-post' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson build-useful-post not found in module 16';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What are the three suggested post purposes?', 
    '["Help, Proof, and Invitation","Sell, Promote, and Advertise","Image, Video, and Text","Morning, Afternoon, and Evening"]'::jsonb,
    'Help, Proof, and Invitation',
    'The three suggested post purposes are Help (answer a question), Proof (share a result), and Invitation (offer a next step).', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How many main next actions should a simple post contain?', 
    '["One","Two","Three","As many as possible"]'::jsonb,
    'One',
    'A simple post should contain one main next action to avoid confusing the reader and make it clear what to do next.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'When should client results or images be used?', 
    '["Only with the right permission and after private information has been removed or approved","Whenever they are available","Only for paid clients","Never, they are not allowed"]'::jsonb,
    'Only with the right permission and after private information has been removed or approved',
    'Client results or images should only be used with the right permission and after private information has been removed or approved.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
